package httpapi

import "net/http"

func (a *API) index(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write([]byte(indexHTML))
}

const indexHTML = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>eink-server</title><style>
:root{font-family:system-ui,sans-serif;color:#1d2520;background:#edf0eb}body{max-width:1100px;margin:2rem auto;padding:0 1rem}h1{font-size:1.7rem}.bar{display:flex;gap:.7rem;align-items:center;flex-wrap:wrap;margin-bottom:1rem}.card,.panel{background:white;border:1px solid #d6dbd4;border-radius:10px;padding:1rem;margin:.8rem 0}.card{display:grid;grid-template-columns:minmax(180px,1fr) 2fr;gap:1rem}.meta{color:#566159;font-size:.9rem;line-height:1.6}.online{color:#16713b}.offline{color:#9b352d}button,input,select{font:inherit;padding:.45rem;border:1px solid #adb6ad;border-radius:5px}button{background:#234f36;color:white;cursor:pointer}.danger{background:#8b3028}.preview{max-width:100%;max-height:250px;border:1px solid #ddd}.controls{display:flex;gap:.45rem;flex-wrap:wrap;margin:.5rem 0}.wide{min-width:18rem}@media(max-width:650px){.card{grid-template-columns:1fr}}</style></head><body>
<h1>eink-server</h1><div class="bar"><input id="broadcast" type="file" accept="image/png,image/jpeg,image/svg+xml,.svg"><button onclick="sendAll()">Send to all</button><span id="notice"></span></div><main id="devices">Loading…</main>
<section class="panel"><h2>Reusable designs</h2><div class="controls"><input id="designName" placeholder="design-name"><input id="designFile" type="file" accept="image/svg+xml,.svg"><button onclick="uploadDesign()">Upload SVG</button><button onclick="reloadDesigns()">Reload folder</button></div><div id="designList"></div></section>
<section class="panel"><h2>Webhook actions</h2><div class="controls"><input id="actionName" placeholder="action.name"><input id="actionURL" class="wide" placeholder="https://…"><input id="actionTimeout" type="number" value="5000" min="1" max="30000"><button onclick="saveAction()">Save action</button></div><div id="actionList"></div></section>
<script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let designs=[];
async function load(){let [dr,rr,ar]=await Promise.all([fetch('/api/v1/devices'),fetch('/api/v1/designs'),fetch('/api/v1/actions')]);let ds=await dr.json();designs=await rr.json();let actions=await ar.json();designList.innerHTML=designs.map(d=>'<div><code>'+esc(d.id)+'</code> · '+esc(d.name)+(d.unresolved_actions?.length?' · unresolved: '+esc(d.unresolved_actions.join(', ')):'')+'</div>').join('')||'No designs.';actionList.innerHTML=actions.map(a=>'<div><code>'+esc(a.name)+'</code> → '+esc(a.url)+' ('+esc(a.source)+') '+(a.source==='db'?'<button class="danger" onclick="deleteAction(\''+esc(a.name)+'\')">Delete</button>':'')+'</div>').join('')||'No actions.';devices.innerHTML=ds.length?'':'No tablets have connected yet.';for(const d of ds){let c=document.createElement('section');c.className='card';let state=d.connected?'Connected':d.online?'Recently seen':'Offline';let frame=d.desired_frame?esc(d.desired_frame.state)+' #'+esc(d.desired_frame.frame_id):'none';let opts=designs.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.id)+'</option>').join('');c.innerHTML='<div><strong>'+esc(d.name||d.uuid.slice(0,12))+'</strong><div class="meta '+(d.online?'online':'offline')+'">'+state+'<br>'+esc(d.width)+'×'+esc(d.height)+' · FW '+esc(d.firmware)+'<br>Battery '+esc(d.battery)+'% · '+esc(d.temperature)+'°C · Humidity '+esc(d.humidity)+'%<br>Last seen '+new Date(d.last_seen).toLocaleString()+'<br>Frame '+frame+'</div></div><div><img class="preview" src="/api/v1/devices/'+encodeURIComponent(d.uuid)+'/image?t='+Date.now()+'" onerror="this.style.display=\'none\'"><div class="controls"><input class="file" type="file" accept="image/png,image/jpeg,image/svg+xml,.svg"><button class="send">Send file</button></div><div class="controls"><select class="design">'+opts+'</select><button class="assign">Use design</button><button class="clear">Stop dynamic updates</button></div><div class="controls image-settings"><select class="fit"><option>contain</option><option>cover</option><option>stretch</option><option>exact</option></select><select class="background"><option>white</option><option>black</option></select><select class="rotation"><option value="0">0°</option><option value="90">90°</option><option value="180">180°</option><option value="270">270°</option></select><select class="dither"><option value="none">No dither</option><option value="floyd-steinberg">Floyd–Steinberg</option></select><select class="rendering"><option value="eink">E Ink crisp</option><option value="smooth">Smooth</option></select><label><input class="invert" type="checkbox"> Invert</label></div><div class="controls"><input class="name" value="'+esc(d.name)+'" placeholder="Device name"><input class="location" value="'+esc(d.location)+'" placeholder="Location"><input class="timezone" value="'+esc(d.timezone)+'" placeholder="Europe/Berlin"><select class="locale"><option value="de-DE">Deutsch</option><option value="en-GB">English</option></select><button class="save">Save settings</button></div></div>';for(const k of ['fit','background','rotation','dither','rendering'])c.querySelector('.'+k).value=String(d.image_defaults[k]);if(d.active_design_id)c.querySelector('.design').value=d.active_design_id;c.querySelector('.locale').value=d.locale;c.querySelector('.invert').checked=d.image_defaults.invert;c.querySelector('.send').onclick=()=>sendOne(d.uuid,c);c.querySelector('.assign').onclick=()=>assign(d.uuid,c);c.querySelector('.clear').onclick=()=>clearDesign(d.uuid);c.querySelector('.save').onclick=()=>save(d.uuid,c);devices.append(c)}}
function settings(c){return {fit:c.querySelector('.fit').value,background:c.querySelector('.background').value,rotation:Number(c.querySelector('.rotation').value),invert:c.querySelector('.invert').checked,dither:c.querySelector('.dither').value,rendering:c.querySelector('.rendering').value}}
async function sendOne(id,c){let f=c.querySelector('.file').files[0];if(!f)return note('Choose a file first');let svg=f.type==='image/svg+xml'||f.name.toLowerCase().endsWith('.svg');let q=svg?'':('?'+new URLSearchParams(settings(c)));let r=await fetch('/api/v1/devices/'+encodeURIComponent(id)+'/image'+q,{method:'PUT',headers:{'Content-Type':svg?'image/svg+xml':f.type},body:f});note(r.ok?'Screen queued':await err(r));load()}
async function sendAll(){let f=broadcast.files[0];if(!f)return note('Choose a file first');let svg=f.type==='image/svg+xml'||f.name.toLowerCase().endsWith('.svg');let r=await fetch('/api/v1/images:broadcast',{method:'POST',headers:{'Content-Type':svg?'image/svg+xml':f.type},body:f});note(r.ok?'Broadcast queued':await err(r));load()}
async function assign(id,c){let r=await fetch('/api/v1/devices/'+encodeURIComponent(id)+'/design',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({design_id:c.querySelector('.design').value})});note(r.ok?'Design assigned':await err(r));load()}
async function clearDesign(id){let r=await fetch('/api/v1/devices/'+encodeURIComponent(id)+'/design',{method:'DELETE'});note(r.ok?'Dynamic updates stopped':await err(r));load()}
async function uploadDesign(){let f=designFile.files[0],name=designName.value;if(!f||!name)return note('Choose an SVG and name');let r=await fetch('/api/v1/designs/'+encodeURIComponent(name),{method:'PUT',headers:{'Content-Type':'image/svg+xml'},body:f});note(r.ok?'Design uploaded':await err(r));load()}
async function reloadDesigns(){let r=await fetch('/api/v1/designs:reload',{method:'POST'});note(r.ok?'Design folder reloaded':await err(r));load()}
async function saveAction(){let r=await fetch('/api/v1/actions/'+encodeURIComponent(actionName.value),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'webhook',url:actionURL.value,timeout_ms:Number(actionTimeout.value),headers:{}})});note(r.ok?'Action saved':await err(r));load()}
async function deleteAction(name){let r=await fetch('/api/v1/actions/'+encodeURIComponent(name),{method:'DELETE'});note(r.ok?'Action deleted':await err(r));load()}
async function save(id,c){let r=await fetch('/api/v1/devices/'+encodeURIComponent(id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:c.querySelector('.name').value,location:c.querySelector('.location').value,timezone:c.querySelector('.timezone').value,locale:c.querySelector('.locale').value,image_defaults:settings(c)})});note(r.ok?'Saved':await err(r));load()}
async function err(r){try{return (await r.json()).error.message}catch{return r.statusText}}function note(s){notice.textContent=s;setTimeout(()=>notice.textContent='',5000)}load();setInterval(load,30000);
</script></body></html>`
